package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class BayesianChecks {
 static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 public static void main(String[] args)throws Exception{
  Path out=Path.of(args[0]);Files.createDirectories(out);Random rng=new Random(66118);double[][] iid=new double[4][2000],ar=new double[4][4000],shifted=new double[4][2000];for(int c=0;c<4;c++){double last=rng.nextGaussian();for(int i=0;i<4000;i++){last=.8*last+.6*rng.nextGaussian();ar[c][i]=last;if(i<2000){iid[c][i]=rng.nextGaussian();shifted[c][i]=rng.nextGaussian()+c;}}}var independent=McmcDiagnostics.summarize(iid,.95);var correlated=McmcDiagnostics.summarize(ar,.95);var notMixed=McmcDiagnostics.summarize(shifted,.95);require(independent.rankSplitRhat()<1.01&&independent.bulkEffectiveSampleSize()>5000,"IID chain convergence / ESS");require(Math.abs(correlated.meanEffectiveSampleSize()-16000.0/9)<600,"AR(1) ESS agrees with theoretical integrated autocorrelation");require(notMixed.rankSplitRhat()>1.3,"Between-chain location failure detected");var constant=McmcDiagnostics.summarize(new double[4][100],.95);require(!Double.isFinite(constant.rankSplitRhat())&&constant.bulkEffectiveSampleSize()==0,"Constant chains never receive false convergence");
  double[][] data=new double[80][1];for(int i=0;i<data.length;i++)data[i][0]=.4+rng.nextGaussian();var model=SimulationChecks.meanModel(0);var options=new BayesianSem.Options(List.of(new BayesianSem.Prior("Mean",BayesianSem.Family.NORMAL,0,1)),4,600,2000,52771,.95,40);int[] progress={0};var fit=BayesianSem.fit(data,model,options,step->{if(step!=++progress[0])throw new AssertionError("False sampler iteration progress");});double average=Arrays.stream(data).mapToDouble(row->row[0]).average().orElseThrow(),posteriorMean=average*80/81,posteriorSD=1/Math.sqrt(81);var summary=fit.terms().getFirst().posterior();require(fit.diagnosticsPassed(),"Known normal-mean posterior passes actual MCMC screens");require(Math.abs(summary.mean()-posteriorMean)<5*summary.meanMonteCarloSE()+.001,"Conjugate posterior mean within Monte Carlo uncertainty");require(Math.abs(summary.standardDeviation()-posteriorSD)<.012,"Conjugate posterior uncertainty");require(progress[0]==10400,"Exact warmup and sampling iteration count");require(fit.predictive().prior().size()==40&&fit.predictive().posterior().size()==40,"Actual prior and posterior predictive replications");var again=BayesianSem.fit(data,model,options,null);var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().create();require(gson.toJson(fit).equals(gson.toJson(again)),"Independent-chain seeded reproducibility");
  double[][] varianceData=new double[100][1];for(var row:varianceData)row[0]=1.2*rng.nextGaussian();var varianceModel=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Variance",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,0)),1,1,1e-7,null)));var varianceOptions=new BayesianSem.Options(List.of(new BayesianSem.Prior("Variance",BayesianSem.Family.LOG_NORMAL,0,.8)),4,600,2000,8821,.95,40);var varianceFit=BayesianSem.fit(varianceData,varianceModel,varianceOptions,null);require(varianceFit.diagnosticsPassed(),"Log-normal variance posterior screens");var posterior=new BayesianSem.Posterior(varianceData,varianceModel,varianceOptions);double ss=Arrays.stream(varianceData).mapToDouble(row->row[0]*row[0]).sum();double a=-.3,b=.4,expected=-50*(b-a)-.5*ss*(Math.exp(-b)-Math.exp(-a))-.5*(b*b-a*a)/(.8*.8);require(Math.abs(posterior.logDensity(new double[]{b})-posterior.logDensity(new double[]{a})-expected)<1e-9,"Log-normal coordinate posterior includes the exact Jacobian");
  var boundedModel=new SemModel.Model(model.variables(),model.observed(),model.directed(),model.covariance(),model.intercepts(),List.of(new SemModel.Parameter("Mean",model.parameters().getFirst().locations(),0,1,-.1,.1)));var boundedFit=BayesianSem.fit(data,boundedModel,new BayesianSem.Options(options.priors(),2,500,2000,77119,.95,40),null);require(boundedFit.chains().stream().allMatch(c->Arrays.stream(c.draws()).allMatch(row->row[0]>=-.1&&row[0]<=.1)),"Configured bounds honored in every retained sample");require(boundedFit.predictive().prior().stream().allMatch(d->Math.abs(d.parameterValues()[0])<=.1),"Prior predictive draws use the same truncated prior support");
  double[][] jointData=new double[100][2];for(var row:jointData){double x=rng.nextGaussian();row[0]=.4+x;row[1]=-.2+.3*x+Math.sqrt(.91)*rng.nextGaussian();}var jointModel=FimlChecks.saturated();var jointPriors=List.of(new BayesianSem.Prior("Variance X",BayesianSem.Family.LOG_NORMAL,0,.6),new BayesianSem.Prior("Variance Y",BayesianSem.Family.LOG_NORMAL,0,.6),new BayesianSem.Prior("Covariance XY",BayesianSem.Family.NORMAL,0,.5),new BayesianSem.Prior("Mean X",BayesianSem.Family.NORMAL,0,2),new BayesianSem.Prior("Mean Y",BayesianSem.Family.NORMAL,0,2));var jointFit=BayesianSem.fit(jointData,jointModel,new BayesianSem.Options(jointPriors,4,1000,2000,6117,.95,40),null);require(jointFit.chains().stream().allMatch(c->Arrays.stream(c.draws()).allMatch(row->row[0]>0&&row[1]>0&&row[0]*row[1]>row[2]*row[2])),"Every joint covariance posterior draw remains positive definite");require(jointFit.terms().stream().allMatch(t->Double.isFinite(t.posterior().rankSplitRhat())),"Joint correlated posterior diagnostics are available");
  double[][] missing=Matrices.copy(data);for(int i=0;i<10;i++)missing[i][0]=Double.NaN;var missingFit=BayesianSem.fit(missing,model,new BayesianSem.Options(options.priors(),2,300,500,882,.95,20),null);require(missingFit.emptyRows()==10&&missingFit.informativeRows()==70,"Missingness enters observed likelihood without replacement");Thread.currentThread().interrupt();try{BayesianSem.fit(data,model,options,null);throw new AssertionError("Bayesian cancellation ignored");}catch(java.util.concurrent.CancellationException expectedFailure){checks++;}finally{Thread.interrupted();}
  JsonObject record=new JsonObject();record.add("data",gson.toJsonTree(data));record.add("fit",gson.toJsonTree(fit));record.add("jointData",gson.toJsonTree(jointData));record.add("jointFit",gson.toJsonTree(jointFit));record.add("boundedFit",gson.toJsonTree(boundedFit));record.add("varianceData",gson.toJsonTree(varianceData));record.add("varianceFit",gson.toJsonTree(varianceFit));record.add("iid",gson.toJsonTree(iid));record.add("iidSummary",gson.toJsonTree(independent));record.add("ar",gson.toJsonTree(ar));record.add("arSummary",gson.toJsonTree(correlated));record.add("shifted",gson.toJsonTree(shifted));record.add("shiftedSummary",gson.toJsonTree(notMixed));record.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),new GsonBuilder().setPrettyPrinting().create().toJson(record));System.out.println("Bayesian SEM checks: "+checks);
 }
}
